const allItems = $input.all();
let mergedData = {};

for (const item of allItems) {
  const j = item.json;
  for (const key in j) {
    if (key.match(/^ch\d+_\d+$/) || key === 'chapter' || key.match(/set/i)) {
      if (typeof j[key] === 'object') {
        mergedData[key] = j[key];
      }
    }
  }
}

function safeExtract(sourceObj) {
  if (!sourceObj) return { main: '', appendix: '', needs: [] };

  const target = sourceObj.output || sourceObj.json || sourceObj;

  return {
    main: (target.content_md_main || '').toString().trim(),
    appendix: (target.content_md_appendix || '').toString().trim(),
    needs: Array.isArray(target.needs) ? target.needs : []
  };
}

const keys = Object.keys(mergedData).sort();
const mainParts = [];
const appendixParts = [];
let allNeeds = [];
let chapterNum = 0;
let chapterTitle = "";

for (const key of keys) {
  const data = safeExtract(mergedData[key]);

  if (data.main) mainParts.push(data.main);
  if (data.appendix) appendixParts.push(data.appendix);
  if (data.needs.length) allNeeds = allNeeds.concat(data.needs);

  const rawObj = mergedData[key].output || mergedData[key];
  if (!chapterNum && rawObj.chapter) chapterNum = rawObj.chapter;
  if (!chapterTitle && rawObj.title) chapterTitle = rawObj.title;
}

if (!chapterNum) {
  chapterNum = 0; 
  chapterTitle = "Chapter Content Merge";
}

return [{
  json: {
    chapter: chapterNum,
    title: chapterTitle,
    content_md_main: mainParts.join('\n\n'),
    content_md_appendix: appendixParts.join('\n\n'),
    needs: [...new Set(allNeeds)].filter(Boolean) 
  }
}];

