const allItems = $input.all();

const chapterMap = new Map();
const allNeeds = [];

function isChapterObj(obj) {
  if (!obj || typeof obj !== 'object') return false;
  if (typeof obj.chapter !== 'number') return false;
  if (typeof obj.title !== 'string') return false;
  return (
    typeof obj.content_md_main === 'string' ||
    typeof obj.content_md_appendix === 'string'
  );
}

function extractChaptersFromJson(json) {
  const found = [];

  if (isChapterObj(json)) {
    found.push(json);
  }

  if (json && typeof json.output === 'object' && isChapterObj(json.output)) {
    found.push(json.output);
  }

  for (const [key, val] of Object.entries(json)) {
    if (!val || typeof val !== 'object') continue;

    const v = val.output && typeof val.output === 'object' ? val.output : val;
    if (isChapterObj(v)) {
      found.push(v);
    }
  }

  return found;
}

for (const item of allItems) {
  const json = item.json || {};
  const candidates = extractChaptersFromJson(json);

  for (const ch of candidates) {
    const chapNo = ch.chapter;
    const title = ch.title;
    const main = typeof ch.content_md_main === 'string' ? ch.content_md_main : '';
    const appendix = typeof ch.content_md_appendix === 'string' ? ch.content_md_appendix : '';
    const needs = Array.isArray(ch.needs)
      ? ch.needs
          .filter(v => typeof v === 'string')
          .map(v => v.trim())
          .filter(v => v !== '')
      : [];

    const existing = chapterMap.get(chapNo);

    if (!existing || main.length > (existing.content_md_main || '').length) {
      chapterMap.set(chapNo, {
        chapter: chapNo,
        title,
        content_md_main: main,
        content_md_appendix: appendix,
        needs,
      });
    }

    if (needs.length) {
      allNeeds.push(...needs); 
    }
  }
}

const chapters = Array.from(chapterMap.values()).sort((a, b) => a.chapter - b.chapter);

const mainParts = [];
const appendixParts = [];

for (const ch of chapters) {
  const main = (ch.content_md_main || '').trim();
  const appendix = (ch.content_md_appendix || '').trim();

  if (main) {

    mainParts.push(`# ${ch.title}\n\n${main}`);
  }
  if (appendix) {
    appendixParts.push(`### Appendix ${ch.chapter}: ${ch.title}\n\n${appendix}`);
  }
}

const mergedProtocol = {
  chapters,
  main_markdown_merged: mainParts.join('\n\n').trim(),
  appendix_markdown_merged: appendixParts.join('\n\n').trim(),
  needs_all: allNeeds,
};

return [{ json: mergedProtocol }];

const chapters = $json.chapters || [];
const mainMerged = $json.main_markdown_merged || '';
const appendixMerged = $json.appendix_markdown_merged || '';
const needsAll = Array.isArray($json.needs_all) ? $json.needs_all : [];

const protocolTitle = 'Research Protocol';

const mdParts = [];
mdParts.push(`# ${protocolTitle}`);
if (mainMerged) mdParts.push(mainMerged);

if (appendixMerged) {
  mdParts.push('\n\n## Appendix A: Supplementary Materials\n');
  mdParts.push(appendixMerged);
